function scrub(value,depth=0) {
  if(depth>15)return '[depth limit]';
  if(typeof value==='string')return value.replace(/\b(?:Bearer\s+)?eyJ[\w.-]+/g,'[credential removed]').replace(/\b(?:sk-|xox[baprs]-)[\w-]+/g,'[credential removed]').replace(/\b(?:authorization|api[-_ ]?key|token|password|secret)\s*[:=]\s*\S+/gi,'[credential removed]');
  if(Array.isArray(value))return value.map(v=>scrub(v,depth+1));
  if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).filter(([k])=>!/^(headers|credentials|authorization|cookie|set-cookie|api[_-]?key|access[_-]?token|refresh[_-]?token|password|secret)$/i.test(k)).map(([k,v])=>[k,scrub(v,depth+1)]));
  return value;
}

function failureRecord(event,response) {
  const execution=event.execution||{},snapshot=response?.data?.resultData?response:response?.body?.data?.resultData?response.body:response;
  const result=snapshot?.data?.resultData||snapshot?.resultData;
  const runData=result?.runData||{};
  const failed=execution.lastNodeExecuted||execution.error?.node?.name||event.trigger?.error?.node?.name||result?.lastNodeExecuted||'Trigger or unknown node';
  const runs=runData[failed]||[],last=runs[runs.length-1];
  let inputs=[],available=false;
  for(const source of last?.source||[]) {
    if(!source)continue;
    const history=runData[source.previousNode]||[];
    const prior=history[source.previousNodeRun??history.length-1];
    const items=prior?.data?.main?.[source.previousNodeOutput??0];
    if(items){inputs.push({from_node:source.previousNode,items:items.map(x=>x.json)});available=true}
  }
  const archive=runData['Archive raw transcript']?.[0]?.data?.main?.[0]?.[0]?.json;
  const message=scrub(String(execution.error?.message||event.trigger?.error?.message||'Execution failed')).replace(/https?:\/\/\S+/g,'[URL removed]').slice(0,2000);
  return {workflow_name:String(event.workflow?.name||'Post-Call Revenue Intelligence').slice(0,200),
    failed_node:String(failed).slice(0,200),error_message:message,execution_id:execution.id?String(execution.id):null,
    failed_input:scrub({available,reason:available?null:'Input unavailable: execution not saved, API unavailable, trigger failure or missing source data',transcript_id:archive?.id||null,inputs})};
}

return [{json:failureRecord($('Catch workflow error').first().json,$json)}];
